CREATE FUNCTION on_delete_team()
  RETURNS TRIGGER AS $func$
  BEGIN
    UPDATE storage_object
       SET deleted_at = now()
     WHERE id = OLD.photo_id;

    RETURN OLD;
  END;
$func$ LANGUAGE plpgsql

CREATE FUNCTION handle_page_update()
  RETURNS TRIGGER AS $pagechange$
  DECLARE
    current_dt timestamptz := clock_timestamp();
    proj_id uuid;
  BEGIN
    NEW.modified_at := current_dt;

    UPDATE file
       SET modified_at = current_dt
     WHERE id = OLD.file_id
 RETURNING project_id
      INTO STRICT proj_id;

    --- Update projects modified_at attribute when a
    --- page of that project is modified.
    UPDATE project
       SET modified_at = current_dt
     WHERE id = proj_id;

    RETURN NEW;
  END;
$pagechange$ LANGUAGE plpgsql

CREATE FUNCTION on_media_object_insert()
  RETURNS TRIGGER AS $$
  BEGIN
    UPDATE file
       SET has_media_trimmed = false,
           modified_at = now()
     WHERE id = NEW.file_id;
    RETURN NEW;
  END;
$$ LANGUAGE plpgsql

CREATE FUNCTION handle_delete()
  RETURNS TRIGGER AS $pagechange$
  BEGIN
    INSERT INTO pending_to_delete (type, data)
    VALUES (TG_TABLE_NAME, row_to_json(OLD));
    RETURN OLD;
  END;
$pagechange$ LANGUAGE plpgsql

CREATE FUNCTION handle_file_update()
  RETURNS TRIGGER AS $pagechange$
  DECLARE
    current_dt timestamptz := clock_timestamp();
  BEGIN
    NEW.modified_at := current_dt;

    --- Update projects modified_at attribute when a
    --- page of that project is modified.
    UPDATE project
       SET modified_at = current_dt
     WHERE id = OLD.project_id;

    RETURN NEW;
  END;
$pagechange$ LANGUAGE plpgsql

CREATE FUNCTION on_delete_file_media_object()
  RETURNS TRIGGER AS $func$
  BEGIN
    UPDATE storage_object
       SET deleted_at = now()
     WHERE id = OLD.media_id;

    IF OLD.thumbnail_id IS NOT NULL THEN
      UPDATE storage_object
         SET deleted_at = now()
       WHERE id = OLD.thumbnail_id;
    END IF;

    RETURN OLD;
  END;
$func$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION on_delete_file_media_object()
  RETURNS TRIGGER AS $func$
  BEGIN
    IF OLD.thumbnail_id IS NOT NULL THEN
      UPDATE storage_object
         SET touched_at = now()
       WHERE id in (OLD.thumbnail_id, OLD.media_id);
    ELSE
      UPDATE storage_object
         SET touched_at = now()
       WHERE id = OLD.media_id;
    END IF;
    RETURN OLD;
  END;
$func$ LANGUAGE plpgsql

CREATE FUNCTION update_modified_at()
  RETURNS TRIGGER AS $updt$
  BEGIN
    NEW.modified_at := clock_timestamp();
    RETURN NEW;
  END;
$updt$ LANGUAGE plpgsql

CREATE FUNCTION on_delete_profile()
  RETURNS TRIGGER AS $func$
  BEGIN
    UPDATE storage_object
       SET deleted_at = now()
     WHERE id = OLD.photo_id;

    RETURN OLD;
  END;
$func$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION raise_deletion_protection()
  RETURNS TRIGGER AS $$
  BEGIN
    RAISE EXCEPTION 'unable to proceed to delete row on \%"', TG_TABLE_NAME
          USING HINT = 'disable deletion protection with "SET rules.deletion_protection TO off"';
    RETURN NULL;
  END;
$$ LANGUAGE plpgsql"

-- Trigger function to sync version -> source (backward compatibility with old code)
CREATE OR REPLACE FUNCTION server_error_report__sync_version_to_source()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.version IS NOT NULL AND NEW.source IS NULL THEN
    NEW.source := NEW.version;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql
